using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 static readonly string[] SalvageNames={"Abandoned provision chest","Evacuee's travel pack","Triage medical locker","Memorial emergency tin","Workshop tool chest","Checkpoint ammunition case"};
 void SpawnSalvageCaches(){if(dungeon!=null)return;SpawnAbandonedStops();foreach(var p in props.ToArray())if(p.Kind==15&&game.World.Changes.OpenedSalvage.Contains(p.Id)){p.Node.QueueFree();props.Remove(p);uniqueObjects.Remove(p.Id);}foreach(var story in props.Where(p=>p.Kind==16||p.Kind==8&&p.Node.HasMeta("story_kind")).ToArray()){
  int kind=story.Kind==16?(story.Material==0?1:4):story.Node.GetMeta("story_kind").AsInt32();string id=story.Id+"/salvage";if(uniqueObjects.Contains(id)||game.World.Changes.OpenedSalvage.Contains(id))continue;var position=story.Node.ToGlobal(new Vector3(-4,0,2.7f));position.Y=(float)game.World.Height(position.X,position.Z);if(!OutdoorFree(position.X,position.Z)||game.Building.Pieces.Any(b=>ExpeditionGame.Distance(b.X,b.Z,position.X,position.Z)<3))continue;var n=new Node3D{Position=position,Rotation=story.Node.Rotation};worldRoot.AddChild(n);DressSalvage(n,kind);int tier=game.World.Tier(position.X,position.Z);props.Add(new(){Id=id,Kind=15,Node=n,Position=position,Material=kind,Tier=tier});uniqueObjects.Add(id);
 }}
 void DressSalvage(Node3D n,int kind){var color=kind==2?new Color(.65f,.62f,.49f):kind==5?new Color(.25f,.32f,.23f):kind==1?Cloth:Wood;Bevel(n,new(0,.35f,0),new(1.1f,.7f,.7f),color);Box(n,new(0,.73f,0),new(1.15f,.06f,.76f),Steel);for(int side=-1;side<=1;side+=2){Box(n,new(side*.38f,.36f,-.36f),new(.07f,.60f,.025f),Steel);Tube(n,new(side*.60f,.43f,-.16f),new(side*.60f,.43f,.16f),.025f,Steel);}if(kind==2){Box(n,new(0,.40f,-.37f),new(.30f,.08f,.02f),new(.67f,.12f,.08f));Box(n,new(0,.40f,-.38f),new(.08f,.30f,.02f),new(.67f,.12f,.08f));for(int i=0;i<3;i++)Bevel(n,new(.72f,.13f,i*.16f-.16f),new(.16f,.26f,.12f),new(.65f,.63f,.52f));}else if(kind==4){Tube(n,new(-.3f,.80f,0),new(.32f,.80f,0),.035f,Wood);Box(n,new(.32f,.85f,0),new(.16f,.19f,.08f),Steel);for(int i=0;i<3;i++)Box(n,new(.7f,.07f+i*.10f,0),new(.35f,.08f,.8f),Wood);}else if(kind==5){for(int i=0;i<4;i++)Tube(n,new(-.3f+i*.2f,.77f,0),new(-.3f+i*.2f,.9f,0),.035f,new(.61f,.49f,.23f));for(int i=0;i<3;i++)Ellipsoid(n,new(.65f,.15f,i*.35f-.35f),new(.22f,.15f,.22f),new(.44f,.39f,.25f));}else{for(int i=0;i<3;i++)Tube(n,new(-.25f+i*.25f,.78f,0),new(-.25f+i*.25f,1,0),.075f,kind==1?Steel:new Color(.55f,.41f,.21f));}n.AddChild(new Label3D{Text=SalvageNames[kind].ToUpperInvariant(),Position=new(0,1.3f,0),FontSize=20,PixelSize=.006f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled,Modulate=new(.83f,.77f,.57f)});}
 ExpeditionRelic SalvageRelic(WorldProp p){uint h=game.World.Hash(p.Id.GetHashCodeStable(),731);if(h%100>=18)return null;string slot=new[]{"head","chest","hands","feet"}[(h>>8)%4];string name=slot=="head"?"Rescuer's reinforced hood":slot=="chest"?"Warden's field vest":slot=="hands"?"Machinist's reinforced gloves":"Pathfinder's trail boots";return new(){Id=p.Id+"/rare",Name=name,Origin=SalvageNames[p.Material],Slot=slot,Level=p.Tier,Armor=slot=="chest"?p.Tier*10+6:p.Tier*3+4,Vitality=p.Tier*3+2};}
 bool SearchSalvage(){var p=NearProp(15,2.6f);if(p==null)return false;if(game.World.Changes.OpenedSalvage.Contains(p.Id)){game.Notice="Cache already searched";return true;}var rare=SalvageRelic(p);if(!game.Change(()=>{game.World.Changes.OpenedSalvage.Add(p.Id);game.Craft.Materials[p.Tier==1?2:p.Tier+1]+=2;game.Craft.UnlockedTier=Math.Max(game.Craft.UnlockedTier,p.Tier);if(p.Material==2){game.Life.Bandages+=3;game.Life.Medicine++;}else if(p.Material==4){game.Craft.ScrapMetal+=2;game.Craft.Glass++;game.Craft.Materials[0]+=5;game.Craft.Materials[1]+=3;}else if(p.Material==5)game.Craft.GiveAmmo(p.Tier>=5?4:p.Tier==4?1:p.Tier==3?2:0,12+p.Tier*6);else{game.Life.Food+=2;game.Craft.Water+=2;game.Life.Bandages++;}if(rare!=null)game.Profile.Claim(rare);game.Skills.Survival.Gain(25);game.Career.Gain(20);})){return true;}game.Notice=SalvageNames[p.Material]+" recovered / "+(rare!=null?"RARE: "+rare.Name:p.Material==2?"bandages, medicine and materials":p.Material==4?"timber, stone and materials":p.Material==5?"ammunition and materials":"food, water, bandage and materials");TryScavengeTrap(p);SpawnSalvageCaches();return true;}
}
